def add_legislatura_to_mesa_diretora(apps, schema_editor):
    # As datas próprias da mesa têm precedência: só as vazias recebem as
    # datas da sessão legislativa. Sobrescrevê-las apagaria períodos que a
    # Casa já tinha registrado (ex.: duas mesas na mesma sessão, uma por
    # semestre), que passariam a ser idênticos e sobrepostos.
    schema_editor.execute("""
        UPDATE parlamentares_mesadiretora md
        SET
            legislatura_id = sl.legislatura_id,
            data_inicio = COALESCE(md.data_inicio, sl.data_inicio),
            data_fim = COALESCE(md.data_fim, sl.data_fim)
        FROM
            parlamentares_sessaolegislativa sl
        WHERE
            sl.id = md.sessao_legislativa_id
    """)


def remove_composicoes_sem_mesa(apps, schema_editor):
    """
    O modelo antigo aceitava composição sem mesa (mesa_diretora nulo), resto
    da migração de dados do SAPL 3.0. Essas composições não aparecem em
    nenhuma tela, e a 0050 torna mesa_diretora obrigatório: sem esta
    limpeza, o migrate aborta com IntegrityError e o SAPL não sobe.

    As composições removidas são listadas no log da aplicação e na saída do
    migrate.
    """
    ComposicaoMesa = apps.get_model('parlamentares', 'ComposicaoMesa')
    orfas = ComposicaoMesa.objects.filter(
        mesa_diretora__isnull=True
    ).select_related('parlamentar', 'cargo').order_by('id')

    linhas = ['ComposicaoMesa id={} ({} - {})'.format(
        c.id, c.parlamentar.nome_parlamentar, c.cargo.descricao)
        for c in orfas]
    if not linhas:
        return

    resumo = ('{} ocupação(ões) de cargo na Mesa sem mesa diretora '
              'removida(s): não apareciam em nenhuma tela e impediriam a '
              'migração.').format(len(linhas))
    print('\n  ' + resumo)
    for linha in linhas:
        print('    - ' + linha)
        logger.warning(linha)
    logger.warning(resumo)

    ComposicaoMesa.objects.filter(mesa_diretora__isnull=True).delete()


